// Package cpeclient support handles NVD CPE request construction, validation,
// and response mapping.
package cpeclient

import (
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"time"
)

var (
	partialCPEMatchStringPattern = regexp.MustCompile(`^cpe:2\.3:[aho]:[a-z0-9._-]+:[a-z0-9._-]+$`)
	exactCPEMatchStringPattern   = regexp.MustCompile(`^cpe:2\.3:[aho]:[a-z0-9._-]+:[a-z0-9._-]+:-:\*:\*:\*:\*:[a-z0-9._-]+:\*:\*$`)
)

// newHTTPClient creates the production HTTP client used for CPE API calls.
func newHTTPClient() *http.Client {
	return &http.Client{
		Timeout: 10 * time.Second,
		CheckRedirect: func(request *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}
}

// searchURL builds a CPE API request URL for one validated search mode.
func (c *CPEClient) searchURL(request CPEMatchRequest) (string, error) {
	parsed, err := url.Parse(c.baseURL)
	if err != nil {
		return "", ErrInvalidNVDBaseURL
	}
	values := parsed.Query()
	if request.CPEMatchString != "" {
		values.Set("cpeMatchString", request.CPEMatchString)
	} else {
		values.Set("keywordSearch", request.KeywordSearch)
	}
	parsed.RawQuery = values.Encode()
	return parsed.String(), nil
}

// validateCPEBaseURL validates and normalizes the allowed CPE API endpoint.
func validateCPEBaseURL(baseURL string) (string, error) {
	parsed, err := url.Parse(strings.TrimSpace(baseURL))
	if err != nil {
		return "", ErrInvalidNVDBaseURL
	}
	if parsed.Path != "/rest/json/cpes/2.0" {
		return "", ErrInvalidNVDBaseURL
	}
	if parsed.Scheme == "https" && parsed.Host == officialCPEHost {
		parsed.RawQuery = ""
		parsed.Fragment = ""
		return parsed.String(), nil
	}
	if parsed.Scheme == "http" && isLocalHost(parsed.Hostname()) {
		parsed.RawQuery = ""
		parsed.Fragment = ""
		return parsed.String(), nil
	}
	return "", ErrInvalidNVDBaseURL
}

// normalizeCPEKeywordSearch trims and bounds backend-generated NVD CPE searches.
func normalizeCPEKeywordSearch(keywordSearch string) string {
	keywordSearch = strings.TrimSpace(keywordSearch)
	if len(keywordSearch) > 120 {
		return ""
	}

	fields := strings.Fields(keywordSearch)
	if len(fields) == 0 || len(fields) > 8 {
		return ""
	}
	for _, field := range fields {
		if len(field) > 40 {
			return ""
		}
	}

	return strings.Join(fields, " ")
}

// normalizeCPEMatchString accepts bounded partial or exact CPE forms generated by the service.
func normalizeCPEMatchString(cpeMatchString string) string {
	cpeMatchString = strings.ToLower(strings.TrimSpace(cpeMatchString))
	if !partialCPEMatchStringPattern.MatchString(cpeMatchString) &&
		!exactCPEMatchStringPattern.MatchString(cpeMatchString) {
		return ""
	}
	return cpeMatchString
}

// isLocalHost reports whether a host is allowed for local test wiring.
func isLocalHost(host string) bool {
	switch strings.ToLower(strings.TrimSpace(host)) {
	case "localhost", "127.0.0.1", "::1":
		return true
	default:
		return false
	}
}

type cpeAPIResponse struct {
	Products []cpeProductItem `json:"products"`
}

type cpeProductItem struct {
	CPE cpeItem `json:"cpe"`
}

type cpeItem struct {
	CPEName    string  `json:"cpeName"`
	Deprecated bool    `json:"deprecated"`
	Titles     []title `json:"titles"`
}

type title struct {
	Lang  string `json:"lang"`
	Title string `json:"title"`
}

// mapCPECandidate converts an NVD CPE item into the application's candidate DTO.
func mapCPECandidate(cpe cpeItem) CPECandidate {
	title := cpe.CPEName
	for _, entry := range cpe.Titles {
		if strings.HasPrefix(strings.ToLower(strings.TrimSpace(entry.Lang)), "en") && strings.TrimSpace(entry.Title) != "" {
			title = strings.TrimSpace(entry.Title)
			break
		}
	}

	return CPECandidate{
		CPEName:    strings.TrimSpace(cpe.CPEName),
		Title:      title,
		Deprecated: cpe.Deprecated,
	}
}
